    public byte[] encrypt(String str, byte[] key) {
        try {
            Cipher c = Cipher.getInstance("AES/ECB/PKCS5Padding");
            c.init(Cipher.ENCRYPT_MODE, new SecretKeySpec(normalizeKey(key), "AES"));
            return c.doFinal(str.getBytes(StandardCharsets.UTF_8));
        } catch (Exception e) {
            throw new RuntimeException("AES encrypt", e);
        }
    }

    public String decrypt(byte[] data, byte[] key) {
        try {
            Cipher c = Cipher.getInstance("AES/ECB/PKCS5Padding");
            c.init(Cipher.DECRYPT_MODE, new SecretKeySpec(normalizeKey(key), "AES"));
            return new String(c.doFinal(data), StandardCharsets.UTF_8);
        } catch (Exception e) {
            return "";
        }
    }

    private byte[] normalizeKey(byte[] key) {
        byte[] k = new byte[16];
        for (int i = 0; i < 16; i++) {
            k[i] = key[i % key.length];
        }
        return k;
    }
